function debounce(fn, espera = 300) {
  let temporizador;
  return (...args) => {
    clearTimeout(temporizador);
    temporizador = setTimeout(() => fn(...args), espera);
  };
}

function throttle(fn, intervalo = 300) {
  let bloqueado = false;
  return (...args) => {
    if (bloqueado) return;
    fn(...args);
    bloqueado = true;
    setTimeout(() => { bloqueado = false; }, intervalo);
  };
}

function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn(...args);
    return (...proximos) => curried(...args, ...proximos);
  };
}

const somarTres = curry((a, b, c) => a + b + c);
somarTres(1)(2)(3);   // 6
somarTres(1, 2)(3);   // 6 - também funciona parcial

function memoize(fn) {
  const cache = new Map();
  return (...args) => {
    const chave = JSON.stringify(args);
    if (cache.has(chave)) return cache.get(chave);
    const resultado = fn(...args);
    cache.set(chave, resultado);
    return resultado;
  };
}

const fibRapido = memoize(function fib(n) {
  return n <= 1 ? n : fib(n - 1) + fib(n - 2);
});

class EmissorEventos {
  constructor() { this.ouvintes = new Map(); }

  on(evento, callback) {
    if (!this.ouvintes.has(evento)) this.ouvintes.set(evento, []);
    this.ouvintes.get(evento).push(callback);
  }

  emit(evento, ...dados) {
    (this.ouvintes.get(evento) || []).forEach((cb) => cb(...dados));
  }
}

