// tempo limite via Promise.race
function comLimiteDeTempo(promessa, limiteMs = 5000) {
  const tempoEsgotado = new Promise((_, reject) =>
    setTimeout(() => reject(new Error('Tempo limite excedido')), limiteMs)
  );
  return Promise.race([promessa, tempoEsgotado]);
}

// retry com espera entre tentativas
async function tentarNovamente(operacao, tentativas = 3, esperaMs = 500) {
  for (let t = 1; t <= tentativas; t++) {
    try {
      return await operacao();
    } catch (erro) {
      if (t === tentativas) throw erro;
      await new Promise((r) => setTimeout(r, esperaMs));
    }
  }
}
